function dispatch(state,name,args={},context={}){return dispatchCore(state,name,args,{...context,isAndroid,reminderStatus:globalThis.calendarDeviceStatus});}
const $=selector=>document.querySelector(selector);
function fitMobileCalendar(){
  const grid=$('.calendar-grid'),main=$('.main');
  if(!grid||!main||document.body.classList.contains('ai-visible'))return;
  if(!matchMedia('(max-width:680px)').matches){grid.style.removeProperty('height');return;}
  const rows=Number(grid.style.getPropertyValue('--calendar-rows'));
  const foot=grid.parentElement.querySelector('.calendar-foot');
  // Measure in the scrolling content's coordinates, so a resize or refresh
  // while reading daily details does not change the month height.
  const top=grid.getBoundingClientRect().top-main.getBoundingClientRect().top+main.scrollTop;
  const available=main.clientHeight-top-(foot?.getBoundingClientRect().height??33)-8;
  grid.style.height=Math.max(rows*64,Math.floor(available))+'px';
}
addEventListener('resize',()=>requestAnimationFrame(fitMobileCalendar));
